+body { margin: 0; }
+.doc h2 { margin: 0 0 6px; font: 600 19px/1.25 Georgia, "Iowan Old Style", serif; }
+.doc p { margin: 0 0 6px; }
+.doc .lost { color: #59514a; }
+.doc b { font-weight: 600; }
