+<!DOCTYPE html>
+<html lang="en"><head>
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<meta charset="utf-8">
+<title>Dispatch dashboard</title>
+</head>
+<body>
+<x-dc>
+<helmet>
+<style>
+body { margin: 0; }
+.dd {
+  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", "URW Palladio L", Georgia, serif;
+  --sans: system-ui, -apple-system, "Segoe UI", Ubuntu, Cantarell, "Noto Sans", sans-serif;
+  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, "Liberation Mono", monospace;
+  --r-tag: 4px; --r: 8px; --r-card: 12px; --r-panel: 14px; --tap: 44px;
+  --outer: light-dark(#e8e4dd, #0d0b09);
+  --bg: light-dark(#f9f6f1, #1a1713);
+  --card: light-dark(#fffdfa, #23201c);
+  --sunk: light-dark(#f0ece5, #13100d);
+  --ink: light-dark(#251e18, #ebe7e0);
+  --muted: light-dark(#59514a, #b8b3ac);
+  --line: light-dark(#d5d0c8, #433f3a);
+  --line-strong: light-dark(#867f77, #847f78);
+  --accent: light-dark(#1a6444, #82d2a8);
+  --accent-hover: light-dark(#005031, #9fe7c0);
+  --on-accent: light-dark(#fcfaf6, #0e1913);
+  --accent-soft: light-dark(#dbf2e4, #1b3427);
+  --hl: light-dark(#f7e8af, #4e3e09);
+  --hl-line: light-dark(#815b1f, #ddc276);
+  --focus: light-dark(#0267c7, #7dbaff);
+  --bad: light-dark(#a8201a, #ff9e94);
+  --wait: light-dark(#6a3a9e, #cdb4f5);
+  --small: 14px;
+  container: page / inline-size;
+  min-height: 100vh; box-sizing: border-box;
+  background: var(--bg); color: var(--ink);
+  font: 400 15px/1.45 var(--sans);
+  -webkit-text-size-adjust: 100%;
+}
+.dd *, .dd *::before { box-sizing: border-box; }
+.dd a { color: var(--accent); text-underline-offset: 2px; }
+.dd a:hover { color: var(--accent-hover); }
+.dd :focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-radius: 3px; }
+.dd h1, .dd h2, .dd h3, .dd p { margin: 0; }
+.dd h2 { font: 600 20px/1.2 var(--serif); }
+.dd h3 { font: 600 var(--small)/1.3 var(--sans); }
+.m { font-family: var(--mono); font-variant-numeric: tabular-nums; }
+a.tgt { display: inline-flex; align-items: center; min-height: 44px; }
+.mut { color: var(--muted); }
+.sm { font-size: var(--small); }
+.nowrap { white-space: nowrap; }
+
+/* prototype switch: not part of the page */
+.proto { display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center; padding: 8px 16px; background: var(--outer); font-size: 14px; color: var(--muted); }
+.proto label { display: flex; gap: 8px; align-items: center; }
+.proto select { min-height: 36px; }
+
+/* status strip: sticky on every viewport, carries the newest tick */
+.strip { position: sticky; top: 0; z-index: 5; background: var(--bg); border-bottom: 1px solid var(--line); }
+.strip.alarm { background: var(--sunk); border-bottom: 2px solid var(--line-strong); }
+.stripIn { display: flex; align-items: center; gap: 8px 12px; max-width: 1200px; margin: 0 auto; padding: 6px 16px; min-height: 48px; }
+.brand { display: flex; align-items: center; gap: 6px; flex: none; font: 600 18px/1 var(--serif); }
+.brand svg { width: 28px; height: 28px; display: block; }
+.brand span { display: none; }
+.tick { flex: 1 1 auto; min-width: 0; font-size: 14px; line-height: 1.25; }
+.tick b { font-weight: 600; }
+.stripLinks { display: flex; gap: 12px; flex: none; align-items: center; font-size: 14px; }
+.stripLinks a { display: inline-flex; align-items: center; min-height: 44px; }
+.ver { display: none; }
+
+/* the status mark: one role, one key cap */
+.mk { display: inline-flex; flex: none; align-items: center; justify-content: center; width: 18px; height: 18px; border: 1px solid currentColor; border-radius: 3px; font: 700 14px/1 var(--mono); vertical-align: -3px; }
+.r-needs { color: var(--hl-line); }
+.mk.r-needs { background: var(--ink); color: var(--bg); border-color: var(--ink); }
+.mk.r-needs::before { content: ""; width: 12px; height: 13px; background: radial-gradient(circle at 50% 26%, currentColor 0 24%, transparent 26%), radial-gradient(ellipse 50% 44% at 50% 100%, currentColor 0 98%, transparent 100%); }
+.r-working, .r-well { color: var(--accent); }
+.r-waiting { color: var(--wait); }
