+.answer.loud p { color: var(--ink); }
+.banner { display: flex; gap: 10px; align-items: flex-start; padding: 12px 16px; background: var(--sunk); border: 2px solid var(--line-strong); border-radius: var(--r-card); }
+.banner h2 { font-size: 18px; }
+
+.grid { display: flex; flex-direction: column; gap: 16px; }
+.panel { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: var(--r-panel); padding: 12px 12px 14px; min-width: 0; }
