+.quote { margin: 4px 0 6px; padding: 8px 10px; background: var(--sunk); border-radius: var(--r); font: 400 14px/1.5 var(--mono); white-space: pre-wrap; overflow-wrap: anywhere; }
+.path { user-select: all; overflow-wrap: anywhere; }
+
+/* copy control: one word, the same everywhere; it touches only the reader's clipboard */
