+.kv dd span { min-width: 0; overflow-wrap: anywhere; user-select: text; }
+.qTools { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 2px; }
+
+/* an account row: the row is the cap, each cell one slot */
