+.qGroup.first { border-top: 0; margin-top: 0; padding-top: 0; }
+.qItem { display: flex; flex-direction: column; gap: 1px; padding: 5px 0; }
+.qItem.rest { display: none; }
+.qList.all .qItem.rest { display: flex; }
+.ghost { display: flex; gap: 8px; align-items: flex-start; margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--line-strong); color: var(--muted); font-size: var(--small); }
+
+/* window and log */
+.seg { display: flex; flex-wrap: wrap; gap: 6px; }
+.fbtn { min-height: 44px; padding: 4px 10px; background: var(--card); color: var(--ink); border: 1px solid var(--line-strong); border-radius: var(--r-tag); font: 400 14px/1.2 var(--sans); cursor: pointer; display: inline-flex; gap: 6px; align-items: center; }
+.fbtn[aria-pressed="true"] { background: var(--ink); color: var(--bg); border-color: var(--ink); font-weight: 600; }
+.fbtn[aria-pressed="true"] .mk { color: var(--bg); border-color: var(--bg); }
