+.active { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 10px; font-size: var(--small); }
+.linkLine { margin-top: 6px; font-size: 14px; color: var(--muted); overflow-wrap: anywhere; }
+.meta { margin: 10px 0 2px; font-size: var(--small); color: var(--muted); }
